/**
 * The snapshot adapter: a `GET /control/snapshot` answer in, one text-free
 * `ui-bridge/density-capture@1` out, as an `Observation`.
 *
 * It reads text exactly once — lengths, hashes, shapes, the role probe and the
 * targets' `text` matchers — and drops it. Nothing it returns holds page text.
 *
 * It takes `input` as `unknown` on purpose, as `PageHealthInput` does: "there
 * was no `elements` array" is an answer it must be able to give, and coercing a
 * missing array to `[]` at the call site is exactly how "could not see" once
 * rendered as "the page is blank".
 *
 * The unknown codes are the plan's table D-D, mapped once here:
 *
 * | Situation | Answer |
 * |---|---|
 * | an error envelope (`success: false`), or the adapter throws | `unknown{producer_failed}` |
 * | `_meta.stale` | `unknown{stale_input}` |
 * | no `elements` array, or no usable `viewport` block | `unknown{input_missing}` |
 * | zero elements and zero components | `unknown{producer_not_run}` |
 * | the role probe does not match | `unknown{input_missing}` (a snapshot taken as this role is the missing input) |
 * | a redacted text | `chars: null`; coverage `text`, `not_attempted_by_policy` |
 * | a field the snapshot does not carry | the item's field is `null`; coverage named for the field, `input_missing` |
 *
 * The structure pass (`structure.ts`, `resolveDensityStructure`) runs here,
 * because it reads the xpath and the stable ref, which the capture does not
 * keep: it fills `parent`, `path`, `structureBy`, `landmark`, `ownChars` and
 * `blockKey`, and the capture says `structureResolved: true`.
 *
 * Plan: 2026-11-23-ui-bridge-measures-information-density-as-reach-per-role-and-plans-the-change (Phases 1 and 3).
 */

import { Observation, type ObservationTime, type UnknownCode } from '../observation/observation';
import { densityTargetsHash, densityTextHash, sha256DensityHex } from './hash';
import { collectDensityTextMatchers, evaluateDensityTextMatchers } from './match';
import {
  DENSITY_CAPTURE_SCHEMA,
  type DensityCapture,
  type DensityCaptureBases,
  type DensityCaptureViewport,
  type DensityContentCap,
  type DensityItem,
  type DensityProbeResult,
  type DensityProducer,
  type DensityRect,
  type DensityScrollerEvidence,
  type DensityTargets,
  type DensityUnmeasured,
  type DensityVisibility,
  boundDensityItem,
  DENSITY_MAX_COORDINATE_PX,
} from './schema';
import { densityShapeOf } from './shape';
import { resolveDensityStructure, type DensityStructureHint } from './structure';

/** Options of {@link captureDensityFromSnapshot}. */
export interface DensityCaptureOptions {
  /** Who is running the core (D-E). Required: the core cannot know its host. */
  producer: DensityProducer;
  /** The role this snapshot is read as; `null` for a capture with no role. */
  role?: string | null;
  /** The data state the page was loaded with, when the caller names one. */
  fixture?: string | null;
  /** When given, its `text` matchers are evaluated, and the role's probe is checked. */
  targets?: DensityTargets | null;
  /** When the producer ran. Defaults to now; an unparseable value is replaced by now. */
  evaluatedAt?: ObservationTime;
}

export type DensityCaptureObservation = Observation<DensityCapture>;

type Rec = Record<string, unknown>;

function isRecord(v: unknown): v is Rec {
  return v !== null && typeof v === 'object' && !Array.isArray(v);
}

function finite(v: unknown): number | null {
  return typeof v === 'number' && Number.isFinite(v) ? v : null;
}

function str(v: unknown): string | null {
  return typeof v === 'string' ? v : null;
}

function nonEmpty(v: unknown): string | null {
  return typeof v === 'string' && v !== '' ? v : null;
}

function collapse(text: string): string {
  return text.replace(/\s+/g, ' ').trim();
}

/** Code points, not UTF-16 units: an emoji is one character to a reader. */
function codePointLength(text: string): number {
  let n = 0;
  for (const _ of text) n++;
  return n;
}

/** `16px` → 16; anything that is not a px length → `null`. */
function px(v: unknown): number | null {
  if (typeof v !== 'string') return null;
  const m = /^(-?\d+(?:\.\d+)?)px$/.exec(v.trim());
  return m ? Number(m[1]) : null;
}

/** Counts per (dimension, code), in first-seen order. */
class Gaps {
  private readonly counts = new Map<string, DensityUnmeasured>();

  add(dimension: string, code: UnknownCode): void {
    const key = `${dimension}\u0000${code}`;
    const cur = this.counts.get(key);
    if (cur) cur.count++;
    else this.counts.set(key, { dimension, count: 1, code });
  }

  list(): DensityUnmeasured[] {
    return Array.from(this.counts.values()).map((u) => ({ ...u }));
  }
}

function readViewport(v: unknown): DensityCaptureViewport | null {
  if (!isRecord(v)) return null;
  const width = finite(v.viewportWidth);
  const height = finite(v.viewportHeight);
  const scrollX = finite(v.scrollX);
  const scrollY = finite(v.scrollY);
  const documentWidth = finite(v.documentWidth);
  const documentHeight = finite(v.documentHeight);
  const inRange = (v: number | null, min: number): v is number =>
    v !== null && v >= min && v <= DENSITY_MAX_COORDINATE_PX;
  if (
    !inRange(width, 1) ||
    !inRange(height, 1) ||
    !inRange(scrollX, -DENSITY_MAX_COORDINATE_PX) ||
    !inRange(scrollY, -DENSITY_MAX_COORDINATE_PX) ||
    !inRange(documentWidth, 0) ||
    !inRange(documentHeight, 0)
  ) {
    return null;
  }
  const container = v.container === 'viewport' || v.container === 'body' ? v.container : null;
  return { width, height, scrollX, scrollY, documentWidth, documentHeight, container };
}

/** `state.visible` and `state.visibilityReason` → the capture's visibility. */
function readVisibility(state: Rec): DensityVisibility | null {
  if (state.visible === true) return 'rendered';
  if (state.visible !== false) return null;
  switch (state.visibilityReason) {
    // Scrolled away is still rendered: the fold, not visibility, says where it is.
    case 'off-screen':
      return 'rendered';
    case 'occluded':
    case 'hidden':
    case 'no-layout':
      return state.visibilityReason;
    default:
      return null;
  }
}

/** The relationship edges the capture keeps, by source id: first edge wins. */
interface DensityEdges {
  /** `controls` or `toggles`. */
  controls: Map<string, string>;
  /** `filters` (search -> list). */
  filters: Map<string, string>;
}

/** The ids each element controls, toggles or filters, from the snapshot's relationships. */
function relationshipEdges(snapshot: Rec): DensityEdges {
  const out: DensityEdges = { controls: new Map(), filters: new Map() };
  const rel = snapshot.relationships;
  if (!isRecord(rel) || !Array.isArray(rel.relationships)) return out;
  for (const edge of rel.relationships) {
    if (!isRecord(edge)) continue;
    const map =
      edge.type === 'controls' || edge.type === 'toggles'
        ? out.controls
        : edge.type === 'filters'
          ? out.filters
          : null;
    if (map === null) continue;
    const source = str(edge.source);
    const target = str(edge.target);
    if (source !== null && target !== null && !map.has(source)) map.set(source, target);
  }
  return out;
}

interface BuiltItem {
  item: DensityItem;
  /** The collapsed text, kept only until the text matchers and probe are evaluated. */
  text: string | null;
  complete: boolean;
  scrollInfoArea: number | null;
  /** What the row says about the item's place in the DOM, for the structure pass. */
  hint: DensityStructureHint;
}

function buildItem(
  el: Rec,
  id: string,
  viewport: DensityCaptureViewport,
  edges: DensityEdges,
  gaps: Gaps
): BuiltItem {
  let complete = true;
  const miss = (dimension: string, code: UnknownCode = 'input_missing'): void => {
    gaps.add(dimension, code);
    complete = false;
  };
  const hasState = isRecord(el.state);
  const state: Rec = hasState ? (el.state as Rec) : {};
  if (!hasState) miss('state');

  // ---- geometry: viewport space → document space ----
  let rect: DensityRect | null = null;
  if (isRecord(state.rect)) {
    const x = finite(state.rect.x);
    const y = finite(state.rect.y);
    const w = finite(state.rect.width);
    const h = finite(state.rect.height);
    if (x !== null && y !== null && w !== null && h !== null) {
      rect = { x: x + viewport.scrollX, y: y + viewport.scrollY, w, h };
    }
  }
  if (rect === null) miss('rect');

  const visibility = readVisibility(state);
  if (visibility === null) miss('visibility');

  // ---- text: read once, then only lengths, hashes and shapes leave ----
  const redaction = isRecord(state.redaction) ? state.redaction : null;
  let text: string | null = null;
  let chars: number | null = null;
  let textHash: string | null = null;
  let shape: DensityItem['shape'] = null;
  if (redaction && redaction.content === true) {
    miss('text', 'not_attempted_by_policy');
  } else if (!hasState) {
    // No state at all: the text is unknown, not empty.
    miss('text');
  } else {
    // The serializer omits `textContent` when the element has no text (and no
    // aria-label or title to fall back on), so an absent field is empty text.
    const raw = typeof state.textContent === 'string' ? state.textContent : '';
    text = collapse(raw);
    chars = codePointLength(text);
    textHash = chars > 0 ? densityTextHash(text) : null;
    shape = densityShapeOf(text);
  }

  // ---- typography and position ----
  let fontPx: number | null = null;
  let lineHeightPx: number | null = null;
  let position: string | null = null;
  const styles = isRecord(state.computedStyles) ? state.computedStyles : null;
  if (styles) {
    fontPx = px(styles.fontSize);
    if (fontPx === null) miss('fontSize');
    // `normal` depends on the font's metrics, which the snapshot does not carry.
    lineHeightPx = px(styles.lineHeight);
    if (lineHeightPx === null) miss('lineHeight');
    position = str(styles.position);
    if (position === null) miss('position');
  } else {
    miss('computedStyles');
  }

  // ---- truncation ----
  let truncated: boolean | null = null;
  const scrollWidth = finite(state.scrollWidth);
  const clientWidth = finite(state.clientWidth);
  // An empty computed `overflow` (some engines leave the shorthand blank) is not a value.
  const overflowRaw = styles ? str(styles.overflow) : null;
  const overflow = overflowRaw !== null && overflowRaw.trim() !== '' ? overflowRaw : null;
  if (scrollWidth !== null && clientWidth !== null && overflow !== null) {
    // `overflow` may be the two-value shorthand `x y`; horizontal truncation is the x half.
    const overflowX = overflow.trim().split(/\s+/)[0];
    truncated = scrollWidth > clientWidth + 1 && overflowX !== 'visible';
  } else {
    miss('truncation');
  }
  const nameSource = str(state.nameSource) ?? str(el.nameSource);
  const recoverable = nameSource === 'title' ? true : null;

  // ---- identity ----
  // `data-ui-bridge-content` and `data-ui-bridge-test-id` are only ever
  // written by an author. `data-ui-bridge-id` is NOT evidence on its own: the
  // auto-registrar stamps it on every element it registers
  // (`react/useAutoRegister.ts`, `writeStableAttribute`), so on an
  // `origin: 'auto'` row an author's stamp cannot be told from the
  // registrar's, and it is not counted (an undercount, never a flood). A
  // `hook` registration's id is the author's by construction. A row with no
  // `origin` (an older serializer) falls back to the stamp, and says so.
  const dataset = isRecord(state.dataset) ? state.dataset : {};
  const origin = str(el.origin);
  const stamped = typeof el.uiBridgeId === 'string' || typeof dataset.uiBridgeId === 'string';
  const authorOnly =
    typeof dataset.uiBridgeContent === 'string' || typeof dataset.uiBridgeTestId === 'string';
  let authorId: boolean;
  if (origin === 'hook') {
    authorId = true;
  } else if (origin === 'auto') {
    authorId = authorOnly;
    // Inside a redaction boundary the serializer omits `dataset`, so an
    // author-only carrier cannot be seen: that `false` is unmeasured.
    if (!authorOnly && redaction && !isRecord(state.dataset))
      miss('authorId', 'not_attempted_by_policy');
  } else {
    authorId = authorOnly || stamped;
    if (stamped && !authorOnly) miss('origin');
  }

  const category = str(el.category) ?? str(el.kind);
  if (category === null) miss('category');

  const tagName = str(el.tagName);
  if (tagName === null) miss('tag');

  const identifier = isRecord(el.identifier) ? el.identifier : null;
  const xpath = identifier ? str(identifier.xpath) : null;

  const href = str(state.href);

  let scrollInfoArea: number | null = null;
  if (isRecord(state.scrollInfo)) {
    const ch = finite(state.scrollInfo.clientHeight);
    const cw = finite(state.scrollInfo.clientWidth);
    const sh = finite(state.scrollInfo.scrollHeight);
    // Only a scroller that overflows VERTICALLY moves content past the fold.
    if (ch !== null && cw !== null && sh !== null && sh > ch + 1) scrollInfoArea = ch * cw;
  }

  return {
    item: {
      id,
      parent: null,
      path: null,
      structureBy: xpath !== null && xpath !== '' ? 'xpath' : 'geometry',
      tag: tagName !== null ? tagName.toLowerCase() : '',
      role: str(el.role) ?? str(state.role),
      interactive: category === 'interactive',
      authorId,
      landmark: null,
      rect,
      visibility,
      chars,
      ownChars: null,
      blockKey: null,
      siblingKey: null,
      cousinKey: null,
      cousinRowKey: null,
      textHash,
      shape,
      fontPx,
      lineHeightPx,
      position,
      truncated,
      recoverable,
      expanded: typeof state.ariaExpanded === 'boolean' ? state.ariaExpanded : null,
      controls: edges.controls.get(id) ?? null,
      selected: typeof state.ariaSelected === 'boolean' ? state.ariaSelected : null,
      filters: edges.filters.get(id) ?? null,
      href: href !== null && href !== '' ? sha256DensityHex(href) : null,
    },
    text,
    complete,
    scrollInfoArea,
    hint: {
      xpath: xpath !== null && xpath !== '' ? xpath : null,
      htmlId: identifier ? nonEmpty(identifier.htmlId) : null,
      testId: identifier ? nonEmpty(identifier.testId) : null,
      semanticPath: isRecord(el.stableRef) ? nonEmpty(el.stableRef.semanticPath) : null,
    },
  };
}

function contentCapOf(snapshot: Rec, elements: Rec[]): DensityContentCap {
  const registration = isRecord(snapshot.registration) ? snapshot.registration : null;
  const dropped = registration ? finite(registration.contentDropped) : null;
  if (dropped !== null && dropped >= 0 && Number.isInteger(dropped)) {
    return { status: 'reported', dropped };
  }
  return {
    status: 'unreported',
    contentRows: elements.filter((e) => e.category === 'content' || e.kind === 'content').length,
  };
}

function scrollerOf(
  built: BuiltItem[],
  viewport: DensityCaptureViewport
): DensityScrollerEvidence | null {
  const viewportArea = viewport.width * viewport.height;
  for (const b of built) {
    if (b.scrollInfoArea !== null && b.scrollInfoArea >= 0.5 * viewportArea) {
      return { by: 'scroll-info', id: b.item.id };
    }
  }
  if (viewport.documentHeight <= viewport.height + 1) {
    const below = built.filter(
      (b) => b.item.rect !== null && b.item.rect.y + b.item.rect.h > viewport.documentHeight + 1
    ).length;
    if (below > 0) return { by: 'overflowing-items', count: below };
  }
  return null;
}

/**
 * Build the capture of one cell from a control snapshot — the relay's envelope
 * (`{ success, data, _meta }`) or the bare snapshot.
 */
export function captureDensityFromSnapshot(
  input: unknown,
  options: DensityCaptureOptions
): DensityCaptureObservation {
  const producer = options.producer;
  // An unparseable caller time would make every provenance build throw,
  // the catch's included, so it falls back to now.
  const requestedAt = options.evaluatedAt;
  const evaluatedAt =
    requestedAt !== undefined && Number.isFinite(new Date(requestedAt).getTime())
      ? requestedAt
      : new Date();
  const role = options.role ?? null;
  const targets = options.targets ?? null;
  let targetsHash: string | null = null;

  let observedAt: number | null = null;
  let snapshotId: string | null = null;
  const prov = (coverage?: {
    considered: number;
    measured: number;
    unmeasured: DensityUnmeasured[];
  }) =>
    Observation.provenance({
      producer: { id: producer.id, version: producer.version },
      observedAt,
      evaluatedAt,
      coverage,
      source: {
        package: producer.package,
        schema: DENSITY_CAPTURE_SCHEMA,
        snapshotId,
        targetsHash,
      },
    });

  try {
    targetsHash = targets ? densityTargetsHash(targets) : null;
    let snapshot: unknown = input;
    if (isRecord(input) && 'success' in input && ('data' in input || 'error' in input)) {
      if (input.success !== true) {
        const message = str(input.error) ?? 'no error message';
        return Observation.unknown(
          'producer_failed',
          `the snapshot answer was an error: ${message}`,
          prov()
        );
      }
      const meta = isRecord(input._meta) ? input._meta : null;
      if (meta && meta.stale === true) {
        return Observation.unknown(
          'stale_input',
          'the relay marked this snapshot stale (_meta.stale); read a fresh one',
          prov()
        );
      }
      snapshot = input.data;
    }
    if (!isRecord(snapshot)) {
      return Observation.unknown(
        'input_missing',
        'the input is not a control snapshot object',
        prov()
      );
    }
    const takenAt = finite(snapshot.snapshotTakenAtMs) ?? finite(snapshot.timestamp);
    // A timestamp outside the Date range would make the provenance builder
    // throw; it is an unreadable sample time, so the answer carries none.
    observedAt = takenAt !== null && Number.isFinite(new Date(takenAt).getTime()) ? takenAt : null;
    snapshotId = str(snapshot.snapshotId);

    if (!Array.isArray(snapshot.elements)) {
      return Observation.unknown('input_missing', 'the snapshot has no `elements` array', prov());
    }
    const viewport = readViewport(snapshot.viewport);
    if (viewport === null) {
      return Observation.unknown(
        'input_missing',
        'the snapshot has no usable `viewport` block (viewportWidth, viewportHeight, scrollX, scrollY, documentWidth, documentHeight)',
        prov()
      );
    }
    const components = Array.isArray(snapshot.components) ? snapshot.components.length : 0;
    if (snapshot.elements.length === 0 && components === 0) {
      return Observation.unknown(
        'producer_not_run',
        'the snapshot holds zero elements and zero components: nothing has registered yet',
        prov()
      );
    }

    const gaps = new Gaps();
    const edges = relationshipEdges(snapshot);
    const elements = snapshot.elements.filter(isRecord);
    const nonObjects = snapshot.elements.length - elements.length;
    for (let i = 0; i < nonObjects; i++) gaps.add('element', 'input_missing');
    const built: BuiltItem[] = [];
    const seen = new Set<string>();
    for (const el of elements) {
      const id = str(el.id);
      if (id === null || id === '' || seen.has(id)) {
        gaps.add('id', 'input_missing');
        continue;
      }
      seen.add(id);
      const b = buildItem(el, id, viewport, edges, gaps);
      const bounded = boundDensityItem(b.item);
      for (const g of bounded.gaps) gaps.add(g, 'input_missing');
      built.push(bounded.gaps.length === 0 ? b : { ...b, item: bounded.item, complete: false });
    }

    // ---- the role probe ----
    let probe: DensityProbeResult | null = null;
    if (role !== null && targets) {
      const declared = targets.roles.find((r) => r.role === role);
      if (declared && declared.probe) {
        const probeDecl = declared.probe;
        const target = built.find((b) => b.item.id === probeDecl.id);
        if (target && target.text === null) {
          return Observation.unknown(
            'input_missing',
            `the role probe for "${role}" reads item ${probeDecl.id}, whose text is redacted`,
            prov()
          );
        }
        const matched =
          target !== undefined &&
          target.text !== null &&
          target.text.includes(collapse(probeDecl.includes));
        probe = { role, id: probeDecl.id, matched };
        if (!matched) {
          return Observation.unknown(
            'input_missing',
            target === undefined
              ? `the role probe for "${role}" names item ${probeDecl.id}, which is not in the snapshot: no snapshot taken as this role`
              : `the role probe for "${role}" does not match item ${probeDecl.id}: the snapshot was not taken as this role`,
            prov()
          );
        }
      }
    }

    const textMatches = targets
      ? evaluateDensityTextMatchers(
          built.map((b) => ({ id: b.item.id, text: b.text })),
          collectDensityTextMatchers(targets)
        )
      : {};

    const scroller = scrollerOf(built, viewport);
    const bases: DensityCaptureBases = {
      foldBasis: viewport.scrollY === 0 ? 'measured' : 'reprojected',
      pinBasis: 'registered-only',
      scrollBasis: scroller === null ? 'page' : 'inner-scroller',
      scroller,
      contentCap: contentCapOf(snapshot, elements),
    };

    const coverage = {
      considered: snapshot.elements.length,
      measured: built.filter((b) => b.complete).length,
      unmeasured: gaps.list(),
    };

    const capture: DensityCapture = {
      schema: DENSITY_CAPTURE_SCHEMA,
      scope: 'registered',
      cell: {
        role,
        viewport: { width: viewport.width, height: viewport.height },
        fixture: options.fixture ?? null,
      },
      viewport,
      observedAt: observedAt === null ? null : new Date(observedAt).toISOString(),
      snapshotId,
      route: str(snapshot.route),
      capturedBy: { package: producer.package, version: producer.version },
      bases,
      structureResolved: true,
      repeatKeysResolved: true,
      coverage,
      probe,
      targetsHash,
      textMatches,
      items: resolveDensityStructure(
        built.map((b) => b.item),
        built.map((b) => b.hint)
      ),
    };
    return Observation.measured(capture, prov(coverage));
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    // Nothing read so far is trusted here: the failure may have come from it.
    observedAt = null;
    return Observation.unknown(
      'producer_failed',
      `the density capture adapter threw: ${message}`,
      prov()
    );
  }
}
